"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisFaqContent } from "./components/faq-blocks/content";
import View2 from "./components/faq-blocks/variants/03-stacked";
const variants = {"stacked":View2};
export type { ArtemisFaqContact, ArtemisFaqContent, ArtemisFaqLink, ArtemisFaqQuestion, ArtemisFaqSearch } from "./components/faq-blocks/content";
export interface ArtemisFaqBlocksProps { className?: string; variant?: "stacked"; /** The words on the FAQ section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisFaqContent>; }
export function ArtemisFaqBlocks({ className, variant = "stacked", content }: ArtemisFaqBlocksProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal

/** The words on a button or link, and where it goes. */
export interface ArtemisFaqLink {
  label: string;
  href: string;
}

/** A question and its answer. */
export interface ArtemisFaqQuestion {
  /** The question, on the row that opens. */
  question: string;
  /** The answer, shown while the row is open. */
  answer: string;
  /** A short slug, unique in the list, used in the row's element ids. Defaults to the row's position. */
  id?: string;
  /** The topic it belongs to. search shows it on the row and adds a filter tab for each topic, in the order the topics first appear; with no topics it shows no tabs. */
  category?: string;
}

/** A card beside the questions that points to a person. */
export interface ArtemisFaqContact {
  /** A small line over the title. split. */
  label?: string;
  /** The card's heading. */
  title: string;
  /** The paragraph under the heading. */
  description: string;
  /** The card's button. */
  cta: ArtemisFaqLink;
}

/** The words on the search box, its topic tabs and its empty result. */
export interface ArtemisFaqSearch {
  /** The hint in the empty search box. */
  placeholder: string;
  /** The first topic tab, which shows every question. */
  allLabel: string;
  /** The heading shown when no question matches. */
  emptyTitle: string;
  /** The line under that heading. */
  emptyText: string;
}

/** The words on an Artemis FAQ section. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisFaqContent {
  /** The short line above the heading. All layouts. */
  badge: string;
  /** The heading. All layouts. */
  headline: string;
  /** The heading's last words. stacked underlines them; the other layouts run them on after `headline`. Left out, it keeps the layout's own only when `headline` is left out too. */
  headlineAccent?: string;
  /** The paragraph under the heading. All layouts. */
  subhead: string;
  /** The questions, each opening to show its answer. All layouts. numbered and split number them; numbered, ai-workspace, split and search open one at a time, starting with the first; stacked opens any number, starting with the first two. */
  questions: ArtemisFaqQuestion[];
  /** A card with a button beside the questions. ai-workspace and split. */
  contact?: ArtemisFaqContact;
  /** The words on the search box, the topic tabs and the empty result. search. */
  search?: ArtemisFaqSearch;
}

"use client";
// @zeus-internal
import { useId, useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import { ArtemisButton } from "../../../foundations/button";
import { ARTEMIS_EASE_OUT, ARTEMIS_EASE_OUT_CSS } from "../../../lib/ease";
import type { ArtemisFaqContent } from "../content";
const DEFAULT = {
    badge: "FAQs",
    headline: "Frequently asked",
    headlineAccent: "questions",
    subhead: "A few clear answers to help you understand how everything works.",
    questions: [
        { id: "trial", question: "Can I try the product before choosing a plan?", answer: "Yes. Every workspace starts with a 14-day trial, and you can explore the full product without adding a payment method." },
        { id: "invite", question: "How do I bring my team in?", answer: "Invite people by email or share a private join link. You can change roles and access at any time from workspace settings." },
        { id: "import", question: "Can I move my existing work over?", answer: "You can import common file formats or start from a template. Our support team can also help with larger moves." },
        { id: "plans", question: "What is included in each plan?", answer: "Every plan includes the core workspace. Higher plans add more guests, longer history, and organization controls for larger teams." },
        { id: "change-plan", question: "Can I change my plan later?", answer: "Anytime. Upgrades take effect immediately, while downgrades begin at the end of your current billing period." },
    ],
} satisfies ArtemisFaqContent;
const hidden = { opacity: 0, filter: "blur(8px)", y: 18 };
const shown = { opacity: 1, filter: "blur(0px)", y: 0 };
export default function FaqBlocksStacked({ content }: { content?: Partial<ArtemisFaqContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const accent = content?.headline === undefined ? copy.headlineAccent : content.headlineAccent;
    const baseId = useId();
    const reduce = useReducedMotion();
    const [expanded, setExpanded] = useState<ReadonlySet<number>>(() => new Set([0, 1]));
    const toggle = (index: number) => setExpanded(previous => {
        const next = new Set(previous);
        if (next.has(index))
            next.delete(index);
        else
            next.add(index);
        return next;
    });
    return (<section className="art:w-full art:bg-background art:px-4 art:py-16 art:font-sans art:text-foreground art:@min-[640px]/artemis:px-8 art:@min-[640px]/artemis:py-24">
      <div className="art:mx-auto art:grid art:w-full art:max-w-6xl art:gap-12 art:@min-[1024px]/artemis:grid-cols-[0.78fr_1.22fr] art:@min-[1024px]/artemis:gap-20">
        <motion.div className="art:@min-[1024px]/artemis:sticky art:@min-[1024px]/artemis:top-8 art:@min-[1024px]/artemis:self-start" initial={hidden} animate={shown} transition={reduce ? { duration: 0 } : { duration: 0.55, ease: ARTEMIS_EASE_OUT, delay: 0.05 }}>
          <div className="art:flex art:items-center art:gap-2.5">
            <span className="art:size-2.5 art:rounded-full art:bg-primary" aria-hidden="true"/>
            <p className="art:font-medium art:text-sm">{copy.badge}</p>
          </div>
          <h2 className="art:mt-8 art:max-w-md art:text-balance art:font-medium art:text-4xl art:leading-none art:tracking-tight">
            {accent ? `${copy.headline} ` : copy.headline}
            {accent ? <span className="art:relative art:inline-block">
              {accent}
              <span aria-hidden="true" className="art:absolute art:-right-1 art:-bottom-2 art:left-0 art:h-2">
                <span className="art:absolute art:top-0 art:right-0 art:left-2 art:h-0.5 art:-rotate-2 art:bg-primary"/>
                <span className="art:absolute art:right-3 art:bottom-0 art:left-0 art:h-0.5 art:rotate-1 art:bg-primary/60"/>
              </span>
            </span> : null}
          </h2>
          <p className="art:mt-8 art:max-w-sm art:text-pretty art:text-muted-foreground art:text-sm art:leading-6">
            {copy.subhead}
          </p>
        </motion.div>
        <div className="art:flex art:flex-col art:gap-4">
          {copy.questions.map((item, index) => {
            const id = item.id ?? `q${index}`;
            const open = expanded.has(index);
            const triggerId = `${baseId}-${id}-trigger`;
            const contentId = `${baseId}-${id}-content`;
            return (<motion.article layout="position" key={id} className="art:overflow-hidden art:rounded-3xl art:border art:border-border art:bg-background art:transition-colors art:duration-200 art:hover:border-foreground/20" initial={hidden} animate={shown} transition={reduce ? { duration: 0 } : { duration: 0.55, ease: ARTEMIS_EASE_OUT, delay: 0.16 + index * 0.065 }}>
                <ArtemisButton variant="link" size="none" type="button" className="art:justify-center art:select-none art:disabled:pointer-events-none art:disabled:opacity-50 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-auto art:p-0 art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:group art:flex art:min-h-20 art:w-full art:items-start art:gap-5 art:px-5 art:py-5 art:text-left art:outline-none art:transition-colors art:duration-200 art:focus-visible:ring-1 art:focus-visible:ring-inset art:focus-visible:ring-ring/30 art:@min-[640px]/artemis:px-6 art:rounded-full" id={triggerId} aria-expanded={open} aria-controls={contentId} tabIndex={0} onClick={() => toggle(index)} whileTap={reduce ? undefined : { scale: 0.99 }}>
                  <span className="art:min-w-0 art:flex-1 art:pt-1 art:font-medium art:text-xl art:leading-7">{item.question}</span>
                  <span aria-hidden="true" className="art:grid art:size-11 art:shrink-0 art:place-items-center art:rounded-full art:bg-muted art:text-foreground">
                    {open ? (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-minus art:size-4" aria-hidden="true"><path d="M5 12h14"/></svg>) : (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-plus art:size-4" aria-hidden="true"><path d="M5 12h14"/><path d="M12 5v14"/></svg>)}
                  </span>
                </ArtemisButton>
                <section id={contentId} aria-labelledby={triggerId} aria-hidden={!open} style={{ transitionTimingFunction: ARTEMIS_EASE_OUT_CSS }} className={`art:grid art:overflow-hidden art:transition-[grid-template-rows] art:duration-300 art:motion-reduce:transition-none ${open ? "art:grid-rows-[1fr]" : "art:grid-rows-[0fr]"}`}>
                  <div className="art:min-h-0 art:overflow-hidden">
                    <p style={{ transitionTimingFunction: ARTEMIS_EASE_OUT_CSS }} className={`art:max-w-2xl art:px-5 art:text-pretty art:text-muted-foreground art:text-sm art:leading-6 art:transition-[opacity,transform] art:duration-200 art:motion-reduce:transition-none art:@min-[640px]/artemis:px-6 ${open ? "art:translate-y-0 art:opacity-100" : "art:-translate-y-1 art:opacity-0"}`}>
                      <span className="art:block art:pb-6">{item.answer}</span>
                    </p>
                  </div>
                </section>
              </motion.article>);
        })}
        </div>
      </div>
    </section>);
}
